// returns predicted class; proba[RF_N_CLASSES] receives probabilities
static int rf_predict(const float *x, float *proba) {
  for (int c = 0; c < 5; c++) proba[c] = 0;
  rf_tree_0(x, proba);
  rf_tree_1(x, proba);
  rf_tree_2(x, proba);
  rf_tree_3(x, proba);
  rf_tree_4(x, proba);
  rf_tree_5(x, proba);
  rf_tree_6(x, proba);
  rf_tree_7(x, proba);
  rf_tree_8(x, proba);
  rf_tree_9(x, proba);
  rf_tree_10(x, proba);
  rf_tree_11(x, proba);
  rf_tree_12(x, proba);
  rf_tree_13(x, proba);
  rf_tree_14(x, proba);
  rf_tree_15(x, proba);
  rf_tree_16(x, proba);
  rf_tree_17(x, proba);
  rf_tree_18(x, proba);
  rf_tree_19(x, proba);
  rf_tree_20(x, proba);
  rf_tree_21(x, proba);
  rf_tree_22(x, proba);
  rf_tree_23(x, proba);
  int best = 0;
  for (int c = 0; c < 5; c++) { proba[c] /= 24.0f; if (proba[c] > proba[best]) best = c; }
  return best;
}